function* walk(n){yield n;if('children' in n)for(const c of n.children)yield* walk(c)}
function link(node,target){if(!node||!target)return;node.reactions=[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:target.id,navigation:'NAVIGATE',transition:null}]}]}
const map={'Nav Home':'01','Nav Blog':'02','Nav About Us':'04','Nav Contact us':'07','Ft Home':'01','Ft Blog':'02','Ft About us':'04','Ft Contact us':'07','Ft Privacy Policy':'08'};
let count=0;
for(const key of Object.keys(F)){
  const fr=F[key];
  for(const n of walk(fr)){
    if(map[n.name]&&F[map[n.name]].id!==fr.id){link(n,F[map[n.name]]);count++}
    else if(key==='01'&&n.name==='Hero Read More'){link(n,F['03']);count++}
    else if(key==='01'&&n.name==='View All'){link(n,F['02']);count++}
    else if((key==='01'||key==='02')&&n.name==='Category card Business'){link(n,F['05']);count++}
    else if(key==='01'&&n.name==='Button · Read More >'&&n.parent.name==='Featured card'){link(n,F['03']);count++}
    else if(key==='02'&&n.name==='Blog Read More'){link(n,F['03']);count++}
    else if(key==='03'&&n.name==='Author name'){link(n,F['06']);count++}
    else if(key==='05'&&n.name==='Breadcrumb Blog'){link(n,F['02']);count++}
  }
}
const ids={};for(const k in F)ids[k]=F[k].id;
figma.notify('Wired '+count);
return JSON.stringify({wired:count,ids,pageId:page.id});
